    input  x,
    input  y,
    output z
);

    // Internal signals for submodule outputs
    wire a1_out, b1_out;
    wire a2_out, b2_out;

    // First pair: A and B submodules with OR gate
    A a1 (
        .x(x),
        .y(y),
        .z(a1_out)
    );

    B b1 (
        .x(x),
        .y(y),
        .z(b1_out)
    );

    wire or1_out;
    assign or1_out = a1_out | b1_out;

    // Second pair: A and B submodules with AND gate
    A a2 (
        .x(x),
        .y(y),
        .z(a2_out)
    );

    B b2 (
        .x(x),
        .y(y),
        .z(b2_out)
    );

    wire and1_out;
    assign and1_out = a2_out & b2_out;

    // Final XOR combining the OR and AND results
    assign z = or1_out ^ and1_out;

endmodule

// Submodule A: implements z = (x ^ y) & x
module A (
    input  x,
    input  y,
    output z
);

    assign z = (x ^ y) & x;

endmodule

// Submodule B: implements the given truth table
// Truth table derived from the waveform:
// (x,y) -> z
// 00 -> 1
// 10 -> 0
// 01 -> 0
// 11 -> 1
module B (
    input  x,
    input  y,
    output z
);

    // Logic equation: z = (x & y) | (~x & ~y)
    // This matches XNOR behavior: 1 when x == y, 0 otherwise
    assign z = (x & y) | (~x & ~y);

endmodule

