module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal register representing the flip-flop
    reg q_reg;

    // Sequential logic: 2:1 multiplexer controlled by L
    // When L is asserted (1), the register loads r_in (parallel load).
    // When L is deasserted (0), the register captures q_in (shift/feedback).
    always @(posedge clk) begin
        if (L) begin
            q_reg <= r_in;
        end else begin
            q_reg <= q_in;
        end
    end

    // Output assignment
    assign Q = q_reg;

endmodule

