module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            A: next_state = in ? B : A;
            B: next_state = in ? B : B;
            C: next_state = in ? D : A;
            D: next_state = in ? B : C;
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            D: out <= 1'b1;
            default: out <= 1'b0;
        endcase
    end

    // State register (sequential logic with synchronous reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

endmodule

Prob150_review2015_fsmonehot.code:
module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded state signals
    wire S_state, S1_state, S11_state, S110_state, B0_state, B1_state, B2_state, B3_state, Count_state, Wait_state;

    // One-hot decoding
    assign S_state       = state[0];
    assign S1_state      = state[1];
    assign S11_state     = state[2];
    assign S110_state    = state[3];
    assign B0_state      = state[4];
    assign B1_state      = state[5];
    assign B2_state      = state[6];
    assign B3_state      = state[7];
    assign Count_state   = state[8];
    assign Wait_state    = state[9];

    // ============================================
    // Next-state logic (one-hot generation)
    // ============================================

    // S_next: next state is S when in S and d=0, or in S1 and d=0, or in S110 and d=0
    assign S_next = (S_state & ~d) |
                    (S1_state & ~d) |
                    (S110_state & ~d);

    // S1_next: next state is S1 when in S and d=1, or in S11 and d=1
    assign S1_next = (S_state & d) |
                     (S11_state & d);

    // B3_next: next state is B3 when in B2 (always transitions to B3 on next cycle)
    assign B3_next = B2_state;

    // Count_next: next state is Count when in B3 (always transitions to Count on next cycle)
    assign Count_next = B3_state;

    // Wait_next: next state is Wait when in Count and done_counting=1
    assign Wait_next = (Count_state & done_counting);

    // ============================================
    // Output logic
    // ============================================

    // shift_ena: asserted in states B0, B1, B2, B3
    assign shift_ena = B0_state | B1_state | B2_state | B3_state;

    // counting: asserted only in Count state
    assign counting = Count_state;

    // done: asserted only in Wait state when ack=1 (transitioning to S)
    // The specification says: Wait (done=1) --ack=1--> S
    // We interpret 'done' as the output signal that is 1 in the Wait state
    // and the condition for transition. Since the state machine is Moore,
    // 'done' is typically a registered output, but here we implement the
    // combinational logic that would generate it. Based on the transition
    // Wait --ack=1--> S, 'done' is asserted when in Wait and ack=1.
    assign done = Wait_state & ack;

endmodule

