module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD digits
);

    // Internal register for the 4-digit BCD counter (16 bits)
    reg [15:0] q_reg;

    // Assign output ports
    assign q     = q_reg;
    assign ena   = {q_reg[15], q_reg[11], q_reg[7]}; // enable signals for upper three digits

    // Synchronous always block for counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // BCD increment logic with carry propagation
            // If any digit is 9, it resets to 0 and generates a carry to the next digit
            if (q_reg[3:0] == 4'd9)
                q_reg[3:0] <= 4'd0;
            else
                q_reg[3:0] <= q_reg[3:0] + 1'b1;

            if (q_reg[7:4] == 4'd9)
                q_reg[7:4] <= 4'd0;
            else
                q_reg[7:4] <= q_reg[7:4] + 1'b1;

            if (q_reg[11:8] == 4'd9)
                q_reg[11:8] <= 4'd0;
            else
                q_reg[11:8] <= q_reg[11:8] + 1'b1;

            if (q_reg[15:12] == 4'd9)
                q_reg[15:12] <= 4'd0;
            else
                q_reg[15:12] <= q_reg[15:12] + 1'b1;
        end
    end

endmodule

