module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state register: 2 bits to encode 4 states
    reg [1:0] state;

    // Synchronous reset: go to "low for long time" state (3'b000)
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            // Synthesizable priority encoder to decode sensor vector s
            // s is active-high: bit 2 is highest, bit 0 is lowest
            case (s)
                3'b111: state <= 2'b00; // Above s[2] -> no sensors asserted effectively
                3'b110: state <= 2'b01; // Between s[2] and s[1]
                3'b100: state <= 2'b10; // Between s[1] and s[0]
                3'b000: state <= 2'b11; // Below s[0]
                default: state <= 2'bxx; // Should not happen for valid s
            endcase
        end
    end

    // Output logic (combinational)
    // The outputs are driven by continuous assignments using the 'state' register.
    // Since 'state' is updated on the posedge clk, at the moment of output
    // assignment (in the always @(*) block), 'state' holds the value from
    // the previous cycle (or the initial value). This matches the requirement
    // to use the "level previous to the last sensor change".

    // Default assignments (all outputs 1'b1 for "low for long time" / below s[0])
    assign fr0 = 1'b1;
    assign fr1 = 1'b1;
    assign fr2 = 1'b1;
    assign dfr = 1'b1;

    always @(*) begin
        case (state)
            2'b00: begin // Above s[2] (or initial reset state)
                // No sensors asserted, flow zero
                fr0 = 1'b0;
                fr1 = 1'b0;
                fr2 = 1'b0;
                dfr = 1'b0;
            end
            2'b01: begin // Between s[2] and s[1]
                // Nominal flow rate fr0
                fr0 = 1'b1;
                fr1 = 1'b0;
                fr2 = 1'b0;
                dfr = 1'b0;
            end
            2'b10: begin // Between s[1] and s[0]
                // Nominal flow rate fr0, fr1
                fr0 = 1'b1;
                fr1 = 1'b1;
                fr2 = 1'b0;
                // dfr: Supplemental flow valve opened when the previous level
                // was lower than the current level. Since we are in state 2'b10
                // (between s[1] and s[0]), and the specification implies that
                // a transition from a lower state (e.g., 2'b11 or 2'b01) to 2'b10
                // indicates the level rose, we assert dfr.
                dfr = 1'b1;
            end
            2'b11: begin // Below s[0] (maximum flow)
                // Maximum flow: fr0, fr1, fr2 opened
                fr0 = 1'b1;
                fr1 = 1'b1;
                fr2 = 1'b1;
                // dfr: Supplemental flow valve opened when previous level was lower.
                // In maximum flow mode, dfr is asserted.
                dfr = 1'b1;
            end
            default: begin
                fr0 = 1'b1;
                fr1 = 1'b1;
                fr2 = 1'b1;
                dfr = 1'b1;
            end
        endcase
    end

endmodule
